import{_ as i,o as e,c as l,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2023-12-13","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2023-12-13","date":"2023-12-13T00:00:00.000Z","updated":"2023-12-14T00:00:00.000Z","tags":["Ceph","RGW","Bucket Notification","Multi","Site Support","Lifecycle Management","Role Ownership"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-12-13.md","filePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-12-13.md","lastUpdated":1780459816000}'),n={name:"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-12-13.md"};function a(p,t,s,r,_,c){return e(),l("div",null,[...t[0]||(t[0]=[o("<p>本次会议主要讨论了Ceph RGW的多个关键议题，包括Bucket Notification和Multi-Site支持、生命周期过期和删除标记、多站点测试失败以及角色所有权和账户功能的设计。</p><p><strong>主要议题和决定</strong>：</p><ol><li><p><strong>Bucket Notification 和 Multi-Site 支持</strong>：</p><ul><li>讨论了Bucket Notification V2的实现和Multi-Site功能的支持。</li><li>决定将功能标志从“notification syncing”重命名为“notification V2”，以避免混淆，并确认其为全局标志。</li><li>后续行动包括修改功能标志名称，继续测试和合并当前的PR，以便开始迁移路径的实现。</li></ul></li><li><p><strong>生命周期过期和删除标记</strong>：</p><ul><li>讨论了在多站点设置中，生命周期过期操作在版本控制桶中的问题，确认问题源于多站点之间的删除标记版本ID不一致。</li><li>后续行动包括研究并实现一种策略，确保在多站点环境中删除标记的一致性。</li></ul></li><li><p><strong>多站点测试失败</strong>：</p><ul><li>讨论了多站点测试中的崩溃问题，确认问题与PR中的更改有关，具体是关于RGW RADOS处理程序的使用。</li><li>后续行动包括团队成员共同研究问题，考虑是否需要回退PR或寻找其他解决方案。</li></ul></li><li><p><strong>角色所有权和账户工作进展</strong>：</p><ul><li>讨论了角色所有权与账户概念的关系，以及权限模型的设计。</li><li>确认角色应由账户拥有，而不是单个用户，并讨论了权限模型的设计，特别是关于admin caps的使用。</li><li>后续行动包括重新审视和修订角色权限的使用流程，测试账户功能的进展，并考虑如何整合到现有工作流程中。</li></ul></li></ol><p>本次会议强调了代码和功能的清晰性和一致性，以及在设计和实现过程中考虑迁移和兼容性的重要性。</p>",4)])])}const f=i(n,[["render",a]]);export{u as __pageData,f as default};
